<template><section class="diary-board-shell"><div class="diary-board-toolbar"><div><strong>{{activeSettings.titulo || (team?'Tablero del equipo':'Mi tablero de actividades')}}</strong><small>Abre una tarjeta para ver el detalle, editar o registrar avances.</small></div><div class="diary-board-direct"><button type="button" class="diary-primary" @click="$emit('create')">+ Nueva tarea</button><button type="button" @click="$emit('create','soporte')">+ Soporte</button><button type="button" @click="editHeaders">Personalizar tablero</button></div><label v-if="team">Organizar<select v-model="group"><option value="estado">Por estado</option><option value="persona">Por responsable</option></select></label></div><p class="diary-hint">En celular, desliza las columnas. Usa «Ver / editar» o «Mover». En escritorio puedes arrastrar tareas entre estados.</p><p v-if="notice" class="diary-error" role="status">{{notice}}</p><div class="diary-board" aria-label="Tablero de tareas"><section v-for="lane in lanes" :key="lane.key" :class="['diary-lane','lane-'+lane.key]" :style="{'--lane-accent':(activeSettings.colores||{})[lane.key] || ({pendiente:'#8297aa',en_curso:'#3d86be',pausada:'#bb954d',concluida:'#269b7c'})[lane.key] || '#8297aa'}" @dragover.prevent @drop.prevent="drop(lane)"><header><h3>{{lane.name}}</h3><button v-if="group==='estado'" type="button" class="diary-lane-rename" @click="editHeaders" aria-label="Editar encabezado">✎</button><span>{{lane.tasks.length}}</span></header><div class="diary-lane-cards"><article v-for="t in lane.tasks" :key="t.Id" class="diary-board-card" :class="{'is-late':late(t)}" :data-task-id="t.Id" :draggable="!closed(t) && !busy" @dragstart="drag($event,t)" @dragend="dragged=null"><div class="diary-card-top"><div class="diary-ticket-number">Ticket {{ticketNumber(t)}}</div><div class="diary-card-tags"><span :class="'priority-'+t.Prioridad">{{t.Prioridad}}</span><span v-if="group==='persona'">{{states[t.Estado]}}</span><span v-if="t.Repeticion!=='ninguna'">↻ {{t.Repeticion}}</span></div></div><button type="button" class="diary-card-title" @click="$emit('open',t)"><span v-if="t.Estado==='concluida'">✓ </span>{{t.Titulo}}</button><p class="diary-card-summary">{{t.Indicaciones || 'Sin indicaciones adicionales'}}</p><div class="diary-card-schedule"><div><b>Inicio</b><time>{{date(t.Inicio)}}</time></div><div :class="{'overdue':late(t)}"><b>Fin</b><time>{{date(t.Fin)}}</time><small v-if="late(t)">Vencida</small></div><div v-if="t.FinReal"><b>Cierre</b><time>{{date(t.FinReal)}}</time></div></div><div v-if="t.Proyecto || t.Ticket" class="diary-card-goal">{{t.Proyecto}}</div><button v-if="Number(t.CantidadAdjuntos)>0" type="button" class="diary-card-images" @click.stop="$emit('attachments',t)"><img v-for="image in (previews[t.Id]||[])" :key="image.Id" :src="'/api/index.php/diario/adjuntos/'+image.Id+'?vista=1'" alt="Evidencia de la actividad" loading="lazy" @error="$event.target.style.display='none'"><span>{{t.CantidadAdjuntos}} evidencias</span></button><small v-else class="diary-card-no-evidence">Sin evidencias</small><div v-if="Number(t.Objetivo)>0" class="diary-card-goal">Meta: {{t.Estado==='concluida'?t.Realizado+' / ':''}}{{t.Objetivo}} {{t.Unidad}}</div><div v-if="t.Estado==='concluida'" class="diary-card-grade">{{Number(t.Calidad)>0?'★ '+t.Calidad+' / 5':'Pendiente de calificación'}}</div><footer><span class="diary-avatar" :title="t.ResponsableNombre || t.Usuario">{{initials(t)}}</span><small>{{t.ResponsableNombre || t.Usuario || 'Empleado'}}</small></footer><button v-if="t.TipoTrabajo==='soporte' && !closed(t)" type="button" class="diary-attend-button" @click="$emit('attention',t)">Registrar atención / solución</button><div class="diary-card-actions"><button type="button" @click="$emit('open',t)">Ver / editar</button><select v-if="!closed(t)" aria-label="Mover actividad" :disabled="busy" :value="''" @change="move(t,$event)"><option value="">Mover…</option><option v-if="['pendiente','pausada'].includes(t.Estado)" value="iniciar">{{t.Estado==='pausada'?'Reanudar':'Iniciar'}}</option><option v-if="t.Estado==='en_curso'" value="pausar">Pausar</option><option value="concluir">Concluir y registrar logro</option></select><button v-if="t.Estado==='concluida'" type="button" :disabled="busy" @click="$emit('action',{task:t,action:Number(t.Archivada)?'restaurar':'archivar'})">{{Number(t.Archivada)?'Restaurar':'Archivar'}}</button></div></article><p v-if="!lane.tasks.length" class="diary-lane-empty">Sin tareas {{lane.name.toLowerCase()}}</p><button v-if="lane.key==='pendiente'" type="button" class="diary-lane-add" @click="$emit('create')">+ Nueva tarea</button></div></section><div v-if="!lanes.length" class="diary-board-empty"><strong>Un espacio para cada avance</strong><p>Crea tu primera actividad para organizar el trabajo.</p><button type="button" @click="$emit('create')">+ Nueva actividad</button></div></div><b-modal modal-class="diary-modal-premium" v-model="editOpen" @hidden="$emit('preview',null)" title="Personalizar mi tablero" hide-footer><form class="diary-form" @submit.prevent="$emit('settings',draft)"><div class="diary-theme-options"><button v-for="theme in themes" :key="theme.id" type="button" :class="{chosen:draft.tema===theme.id}" :style="{background:'linear-gradient(135deg,'+theme.colors.join(',')+')',color:['claro','noche'].includes(theme.id)?'#25435a':'white'}" @click="draft.tema=theme.id;draft.fondo=''">{{theme.name}}</button></div><label><input type="checkbox" v-model="draft.entorno.activo"> Personalizar colores del entorno general</label><div v-if="draft.entorno.activo" class="diary-appearance-colors"><label v-for="(label,key) in environmentLabels" :key="key">{{label}}<input type="color" v-model="draft.entorno[key]"></label></div><div class="diary-appearance-colors"><label>Color de botones<input type="color" v-model="draft.acento"></label><label v-for="(name,key) in states" :key="key">Color {{name}}<input type="color" v-model="draft.colores[key]"></label></div><label>Imagen de fondo<input type="file" accept="image/jpeg,image/png,image/webp,image/gif,image/avif,image/bmp" @change="chooseBackground"></label><p class="diary-hint">La imagen se ajusta automáticamente. Vista previa en el tablero; solo se guarda al confirmar.</p><button v-if="draft.fondo" type="button" @click="draft.fondo=''">Quitar imagen de fondo</button><p v-if="settingsError" class="diary-error">{{settingsError}}</p><p v-if="imageError" class="diary-error">{{imageError}}</p><p v-if="imageLoading" role="status">Preparando fondo…</p><label>Nombre del tablero<input v-model="draft.titulo" required maxlength="80"></label><label v-for="(name,key) in states" :key="key">{{name}}<input v-model="draft.nombres[key]" required maxlength="40"></label><p class="diary-hint">Los nombres cambian solo en tu cuenta. Los estados y el historial se conservan.</p><button type="submit" class="diary-primary" :disabled="imageLoading || settingsSaving">{{settingsSaving?'Guardando…':'Guardar personalización'}}</button><button type="button" @click="resetAppearance">Restablecer estilo original</button></form></b-modal></section></template>
<script>
import {diaryThemes,appearanceStyle} from '@/utils/diarioAppearance';
import {taskMillis,ticketNumber} from '@/utils/diario';
export default {props:{tasks:{type:Array,required:true},settingsError:{type:String,default:''},settingsSaving:Boolean,settings:{type:Object,default:()=>({})},team:Boolean,busy:Boolean,now:Number},data(){return {previews:{},environmentLabels:{fondo:'Fondo general',fondoFin:'Segundo color del fondo',encabezado:'Encabezado',panel:'Paneles y tablero'},themes:diaryThemes,imageError:'',imageLoading:false,editOpen:false,draft:{entorno:{activo:false,fondo:'#e9efff',fondoFin:'#d9f4f1',encabezado:'#2454ce',panel:'#ffffff'},titulo:'',nombres:{},colores:{},tema:'noche',acento:'#238d80',fondo:''},group:'estado',dragged:null,notice:'',states:{pendiente:'Pendientes',en_curso:'En curso',pausada:'Pausadas',concluida:'Concluidas',cancelada:'Canceladas'}}},computed:{activeSettings(){return this.editOpen?this.draft:this.settings},lanes(){if(this.group==='persona'&&this.team){const groups={};for(const t of this.tasks){const key=t.EmpleadoKey?'e:'+t.EmpleadoKey:t.IdEmpleado?'e:'+t.IdEmpleado:'u:'+t.Usuario;if(!groups[key])groups[key]={key,name:t.ResponsableNombre||t.Usuario||'Empleado',tasks:[]};groups[key].tasks.push(t)}return Object.values(groups)}return Object.keys(this.states).filter(k=>k!=='cancelada'||this.tasks.some(t=>t.Estado===k)).map(k=>({key:k,name:(this.activeSettings.nombres||{})[k]||this.states[k],tasks:this.tasks.filter(t=>t.Estado===k)}))}},mounted(){this.observeEvidence()},beforeDestroy(){if(this._evidenceObserver)this._evidenceObserver.disconnect()},watch:{tasks:{deep:true,handler(){this.$nextTick(this.observeEvidence)}},group(){this.$nextTick(this.observeEvidence)},draft:{deep:true,handler(){if(this.editOpen)this.$emit('preview',this.draft)}},editOpen(value){if(!value)this.$emit('preview',null)},settings:{deep:true,handler(){this.editOpen=false}}},methods:{ticketNumber,observeEvidence(){if(!window.IntersectionObserver)return;if(!this._evidenceObserver)this._evidenceObserver=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){this._evidenceObserver.unobserve(entry.target);this.loadEvidence(entry.target.dataset.taskId)}})},{rootMargin:'60px'});this.$el.querySelectorAll('.diary-board-card[data-task-id]').forEach(card=>{const task=this.tasks.find(t=>String(t.Id)===card.dataset.taskId);if(task&&Number(task.CantidadAdjuntos)>0){this._evidenceCounts=this._evidenceCounts||{};if(this._evidenceCounts[task.Id]!==Number(task.CantidadAdjuntos)){this.$delete(this.previews,task.Id);this._evidenceCounts[task.Id]=Number(task.CantidadAdjuntos);}if(!this.previews[task.Id])this._evidenceObserver.observe(card)}})},async loadEvidence(id){if(this.previews[id])return;this.$set(this.previews,id,[]);try{const response=await fetch('/api/index.php/diario/tareas/'+id+'/adjuntos',{credentials:'same-origin'});if(!response.ok)return;const data=await response.json();this.$set(this.previews,id,(data.adjuntos||[]).filter(a=>a.VistaPrevia).slice(0,1))}catch(e){}},resetAppearance(){this.draft=Object.assign({},this.draft,{entorno:{activo:false,fondo:'#e9efff',fondoFin:'#d9f4f1',encabezado:'#2454ce',panel:'#ffffff'},tema:'noche',acento:'#238d80',fondo:'',colores:{pendiente:'#8297aa',en_curso:'#3d86be',pausada:'#bb954d',concluida:'#269b7c',cancelada:'#9b7e8f'}})},async chooseBackground(event){const file=event.target.files[0];if(!file)return;this.imageError='';if(!['image/jpeg','image/png','image/webp','image/gif','image/avif','image/bmp'].includes(file.type)||file.size>20*1024*1024){this.imageError='Selecciona una imagen compatible de hasta 20 MB.';event.target.value='';return}this.imageLoading=true;const url=URL.createObjectURL(file);try{const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=reject;image.src=url});const scale=Math.min(1,1600/Math.max(image.width,image.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#17374a';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);let quality=.85,data=canvas.toDataURL('image/jpeg',quality);while(data.length>700000&&quality>.2){quality-=.1;data=canvas.toDataURL('image/jpeg',quality)}if(data.length>700000)throw Error();this.draft.fondo=data}catch(e){this.imageError='No se pudo preparar la imagen. Prueba otra imagen.'}finally{URL.revokeObjectURL(url);event.target.value='';this.imageLoading=false}},editHeaders(){this.imageError='';this.draft={entorno:Object.assign({activo:false,fondo:'#e9efff',fondoFin:'#d9f4f1',encabezado:'#2454ce',panel:'#ffffff'},this.settings.entorno||{}),tema:this.settings.tema||'noche',acento:this.settings.acento||'#238d80',fondo:this.settings.fondo||'',colores:Object.assign({pendiente:'#8297aa',en_curso:'#3d86be',pausada:'#bb954d',concluida:'#269b7c',cancelada:'#9b7e8f'},this.settings.colores||{}),titulo:this.settings.titulo||(this.team?'Tablero del equipo':'Mi tablero de actividades'),nombres:Object.assign({},this.states,this.settings.nombres||{})};this.editOpen=true},closed(t){return ['concluida','cancelada'].includes(t.Estado)},late(t){return !this.closed(t)&&taskMillis(t.Fin)<this.now},date(v){const date=new Date(taskMillis(v));if(!v||isNaN(date.getTime()))return 'Sin fecha';return new Intl.DateTimeFormat('es-PE',{timeZone:'America/Lima',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:false}).format(date)},initials(t){return (t.ResponsableNombre||t.Usuario||'E').trim().split(/\s+/).slice(0,2).map(w=>w[0]).join('').toUpperCase()},move(t,event){const action=event.target.value;event.target.value='';if(action)this.$emit('action',{task:t,action})},drag(event,t){if(this.closed(t)||this.busy){event.preventDefault();return}this.dragged=t;event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',String(t.Id))},drop(lane){const t=this.dragged;this.dragged=null;this.notice='';if(!t||this.busy||lane.key===t.Estado)return;let action='';if(lane.key==='en_curso'&&['pendiente','pausada'].includes(t.Estado))action='iniciar';if(lane.key==='pausada'&&t.Estado==='en_curso')action='pausar';if(lane.key==='concluida'&&!this.closed(t))action='concluir';if(!action){this.notice='Usa Ver / editar para gestionar esta tarea. Las tareas concluidas conservan su historial.';return}this.$emit('action',{task:t,action})}}};
</script>
<style>
.diary-board-shell{background:linear-gradient(130deg,#0a3e51,#076a69);border-radius:20px;padding:20px;color:white}.diary-board-toolbar{display:flex;justify-content:space-between;gap:16px;align-items:center}.diary-board-toolbar strong{font-size:20px}.diary-board-toolbar small{display:block;color:#c3e2e3;margin-top:5px;font-size:12px}.diary-board-toolbar label{min-width:170px;color:#d4efea}.diary-board-shell>.diary-hint{color:#bcdddf}.diary-board{display:flex;gap:16px;overflow-x:auto;align-items:flex-start;padding:6px 0 16px;scroll-snap-type:x proximity;overscroll-behavior-x:contain}.diary-lane{flex:0 0 290px;min-width:0;background:#eaf1f5;border-radius:14px;color:#1a3d51;scroll-snap-align:start}.diary-lane>header{display:flex;justify-content:space-between;align-items:center;padding:16px;border-top:4px solid #8da9bc;border-radius:14px 14px 0 0}.diary-lane>header h3{font-size:14px;margin:0;font-weight:800;overflow-wrap:anywhere}.diary-lane>header>span{background:#d7e4eb;padding:3px 8px;border-radius:10px;font-size:11px}.lane-en_curso>header{border-color:#158ed2}.lane-pausada>header{border-color:#e4ae36}.lane-concluida>header{border-color:#09ac7f}.diary-lane-cards{padding:0 10px 10px;display:flex;flex-direction:column;gap:12px}.diary-board-card{background:white;border:1px solid #dce7ed;border-radius:12px;padding:14px;box-shadow:0 3px 7px #0c324610}.diary-board-card[draggable=true]{cursor:grab}.diary-board-card.is-late{border-left:4px solid #e17b51}.diary-card-tags{display:flex;gap:5px;flex-wrap:wrap;margin-bottom:8px}.diary-card-tags>span{font-size:9px;background:#e8eff4;color:#34576d;border-radius:5px;padding:3px 7px;text-transform:uppercase}.diary-card-tags .priority-urgente{background:#ffe1de;color:#b13a2c}.diary-card-tags .priority-alta{background:#fff0cc;color:#89631b}.diary-card-tags .priority-normal{background:#dff3eb;color:#087955}.diary-page button.diary-card-title{padding:0;background:none;border:0;text-align:left;line-height:1.5;font-size:14px;color:#183f56;white-space:normal;overflow-wrap:anywhere;display:block;width:100%}.diary-board-card>p{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;color:#688092;font-size:12px;margin:8px 0;white-space:pre-wrap;overflow-wrap:anywhere}.diary-card-date{display:inline-block;background:#edf2f6;color:#486779;border-radius:6px;padding:5px 7px;font-size:10px}.diary-card-date.overdue{background:#fff0e6;color:#ac5325}.diary-card-date.finished{background:#dff5e9;color:#087355}.diary-card-goal,.diary-card-grade{font-size:11px;margin-top:8px;color:#3d6476}.diary-board-card footer{display:flex;align-items:center;gap:8px;margin-top:14px}.diary-avatar{border-radius:50%;background:#07876e;color:white;width:28px;height:28px;display:flex;align-items:center;justify-content:center;font-weight:700;font-size:10px;flex:0 0 28px}.diary-board-card footer small{font-size:10px;color:#567386;overflow-wrap:anywhere}.diary-card-actions{display:flex;gap:8px;margin-top:12px;align-items:center}.diary-card-actions>button,.diary-card-actions>select{flex:1;min-width:0;font-size:10px!important;padding:8px!important;border-radius:8px!important}.diary-lane-empty{padding:20px 8px;font-size:12px;color:#718b9b;text-align:center}@media(max-width:800px){.diary-board-shell{padding:14px;border-radius:16px}.diary-board-toolbar{align-items:flex-start;flex-direction:column}.diary-lane{flex-basis:min(290px,calc(100vw - 70px))}.diary-board-toolbar strong{font-size:17px}}

.diary-board-shell{background:linear-gradient(150deg,#eaf0f6,#edf4f5);border:1px solid #dce6ee;border-radius:18px;padding:20px;color:#203c51;box-shadow:0 8px 24px #1a3c5105}
.diary-board-toolbar{padding:0 2px 6px}.diary-board-toolbar strong{font-size:17px;font-weight:700;letter-spacing:-.5px}.diary-board-toolbar small{color:#718699;font-size:11px;margin-top:5px}.diary-board-shell>.diary-hint{color:#8394a5;font-size:10px;margin:4px 2px 16px}.diary-board-toolbar label{font-size:10px;color:#667f91}.diary-board-toolbar select{background:white;border-color:#dbe5ec;font-size:11px;padding:7px 10px}
.diary-board{gap:14px;scrollbar-width:thin;scrollbar-color:#bccedb transparent;padding:5px 0 12px}.diary-lane{flex:1 0 265px;background:#f5f8fa;border:1px solid #dfe8ef;border-radius:13px;min-height:240px;max-width:370px}.diary-lane>header{border:0;padding:16px 14px;border-radius:13px 13px 0 0}.diary-lane>header h3{font-size:12px;letter-spacing:.1px;display:flex;align-items:center;gap:8px}.diary-lane>header h3:before{content:"";width:7px;height:7px;background:#8197ae;border-radius:50%;flex:0 0 7px;box-shadow:0 0 0 3px #8197ae12}.lane-en_curso>header h3:before{background:#438ac8;box-shadow:0 0 0 3px #438ac812}.lane-pausada>header h3:before{background:#d4a348;box-shadow:0 0 0 3px #d4a34812}.lane-concluida>header h3:before{background:#35ac87;box-shadow:0 0 0 3px #35ac8712}.diary-lane>header>span{background:white;border:1px solid #e3eaf0;border-radius:7px;color:#8094a5;font-size:10px;padding:2px 7px}
.diary-board-card{border-color:#e3eaf0;border-radius:11px;padding:15px;box-shadow:0 3px 8px #24425b05;transition:box-shadow .15s,transform .15s}.diary-board-card:hover{box-shadow:0 7px 20px #25465d12;transform:translateY(-2px)}.diary-page button.diary-card-title{font-size:13px;line-height:1.55;letter-spacing:-.2px;font-weight:650;color:#28435a}.diary-card-tags{margin-bottom:10px;gap:5px}.diary-card-tags>span{font-size:8px;padding:3px 6px;letter-spacing:.5px}.diary-board-card>p{font-size:11px;color:#8695a3;line-height:1.65;margin:8px 0 12px}.diary-card-date{font-size:9px;background:#f2f5f8;color:#7a8e9f;padding:5px 7px}.diary-card-date.finished{background:#ecf8f2;color:#399275}.diary-card-date.overdue{background:#fff1ed;color:#b46d50}.diary-card-goal{font-size:10px;color:#7e90a0;margin-top:10px}.diary-card-grade{font-size:10px;color:#269477}.diary-board-card footer{border-top:1px solid #f0f3f6;padding-top:12px;margin-top:12px}.diary-avatar{background:#e5eef4;color:#4b738b;width:25px;height:25px;flex-basis:25px;font-size:9px}.diary-board-card footer small{font-size:10px;color:#8194a3}.diary-card-actions{gap:6px;margin-top:12px}.diary-card-actions>button,.diary-card-actions>select{background:#f9fbfc!important;border-color:#e4ebf1!important;color:#698397!important;font-size:9px!important;padding:7px!important}.diary-lane-empty{margin:3px 4px 10px;padding:42px 12px;background:repeating-linear-gradient(135deg,#f4f8fa,#f4f8fa 6px,#f7fafb 6px,#f7fafb 12px);border:1px dashed #d9e4ec;border-radius:9px;font-size:11px;color:#9aabba}.diary-page button.diary-lane-add{border:1px dashed #cddce6;background:transparent;color:#7490a4;width:100%;font-size:11px;padding:10px;border-radius:9px}.diary-board-empty{padding:40px;min-width:240px;color:#6c8799}.diary-board-empty p{font-size:12px}
@media(max-width:800px){.diary-board-shell{padding:14px 12px}.diary-lane{flex:0 0 min(280px,calc(100vw - 70px));min-height:220px}.diary-board-toolbar strong{font-size:16px}.diary-board-toolbar small{font-size:10px}.diary-board-toolbar{gap:10px}.diary-board-shell>.diary-hint{font-size:9px}.diary-board-toolbar label{min-width:160px}}
